<script setup lang="ts">
import {usePayrollPage} from '../payrollPage'
import type {ChangeMonthDraft} from '../payChanges'
import PayItemFields from './PayItemFields.vue'
defineProps<{months:ChangeMonthDraft[];busy:boolean}>()
const emit=defineEmits<{remove:[index:number];baseline:[month:ChangeMonthDraft]}>(),{english}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
</script>
<template><section v-for="(m,i) in months" :key="i" class="wf-section"><div class="wf-toolbar"><label>{{x('月份','Month')}}<input v-model="m.month" type="month" required :disabled="m.fixed" @change="emit('baseline',m)" :aria-label="x('月份 ','Month ')+(i+1)"></label><button type="button" :disabled="busy||m.fixed" @click="emit('remove',i)">{{x('移除月份','Remove month')}}</button></div><p v-if="m.error" role="alert">{{m.error}} <button type="button" @click="emit('baseline',m)">{{x('重试读取基线','Retry baseline')}}</button></p><p v-if="m.loading" role="status">{{x('读取有效月度输入…','Loading effective monthly input…')}}</p><p v-if="m.fixed" class="wf-hint">{{x('已归入申请的月份保持在同一聚合中；可修订内容。','Saved months remain in this request; their content can be revised.')}}</p><fieldset :disabled="!m.loaded||m.loading"><p class="wf-hint">{{x('月份输入独立于工资批次。自动生成的核定单位以现有规则为准。','Monthly inputs belong to the employee and month; generated units follow existing rules.')}}</p><div class="wf-grid"><label>{{x('工作日数（手工口径）','Working days (manual basis)')}}<input v-model="m.input.workingDays" inputmode="decimal"></label><label>{{x('计薪日数（手工口径）','Payable days (manual basis)')}}<input v-model="m.input.payableDays" inputmode="decimal"></label></div><label><input v-model="m.input.unitsReviewed" type="checkbox">{{x('已核对单位','Units reviewed')}}</label><label><input v-model="m.input.specialDaysReviewed" type="checkbox">{{x('已核对特殊日','Special days reviewed')}}</label><PayItemFields :month="m.month" :items="m.input.items" :disabled="busy"/><label><input type="checkbox" :checked="!!m.input.cdacReview" @change="m.input.cdacReview=m.input.cdacReview?null:{amount:'',note:''}">{{x('CDAC手工复核','Manual CDAC review')}}</label><div v-if="m.input.cdacReview" class="wf-grid"><label>{{x('CDAC金额','CDAC amount')}}<input v-model="m.input.cdacReview.amount" required inputmode="decimal"></label><label>{{x('CDAC复核说明','CDAC review note')}}<textarea v-model="m.input.cdacReview.note" required maxlength="500"/></label></div><label>{{x('月份说明','Monthly note')}}<textarea v-model="m.input.note" maxlength="500"/></label></fieldset></section></template>
